import{TORNADO_CONFIG as n}from"./config.min.js";import*as b from"../../shared/js/narration-1.0.0.min.js";export function beatIndexAt(t,r=n){return b.beatIndexAt(t,r.narration.beats)}export function beatText(t,r="cow",a=n){const e=a.narration.beats[t];return e?e.landed?`${(a.payloads[r]||a.cow).landed} ${a.narration.rainbow}`:e.text:""}export function createNarrator(t,r=n){return b.createNarrator(t,{beats:r.narration.beats,say:(a,e,o="cow")=>beatText(e,o,r)})}
